import numpy as np

class Neohookean:
    def __init__(self, mu_lamé: float, lambda_lamé: float):
        self.μ = mu_lamé
        self.λ = lambda_lamé

    def E(self, F: np.ndarray) -> float:
        """
        based on Psi_B from "Stable Neo-Hookean Flesh Simulation" [Smith et al. 2018]
        E = C (J^{-2/3} trace(F^T F) - 3) + D (J - 1)^2
        not sure if this just doesn't apply in 2D, let's just keep going and see
        """
        J = np.linalg.det(F)
        return (0.5 * self.μ * (J ** (-2 / 3) * np.linalg.trace(F.T @ F) - 3)
                + 0.5 * self.μ * (J - 1) ** 2)


    def dE_dF(self, F: np.ndarray) -> np.ndarray:
        # used matlab lol
        F1_1 = F[0, 0]
        F1_2 = F[0, 1]
        F1_3 = F[0, 2]
        F2_1 = F[1, 0]
        F2_2 = F[1, 1]
        F2_3 = F[1, 2]
        F3_1 = F[2, 0]
        F3_2 = F[2, 1]
        F3_3 = F[2, 2]

        # factor out common terms
        J = np.linalg.det(F)
        J_neg_2_3 = J ** (-2. / 3.)
        J_neg_5_3 = J ** (-5. / 3.)
        F_sqnorm = np.linalg.norm(F) ** 2
        F_11_22_m = F[0, 0] * F[1, 1] - F[0, 1] * F[1, 0]
        F_11_32_m = F[0, 0] * F[2, 1] - F[0, 1] * F[2, 0]
        F_21_32_m = F[1, 0] * F[2, 1] - F[1, 1] * F[2, 0]
        F_11_23_m = F[0, 0] * F[1, 2] - F[0, 2] * F[1, 0]
        F_12_23_m = F[0, 1] * F[1, 2] - F[0, 2] * F[1, 1]
        F_11_33_m = F[0, 0] * F[2, 2] - F[0, 2] * F[2, 0]
        F_21_33_m = F[1, 0] * F[2, 2] - F[1, 2] * F[2, 0]
        F_12_33_m = F[0, 1] * F[2, 2] - F[0, 2] * F[2, 1]
        F_22_33_m = F[1, 1] * F[2, 2] - F[1, 2] * F[2, 1]

        # F was flattened row-wise, as in lecture
        # @formatter:off
        out = np.zeros(9)
        out[0] = 0.5 * self.μ * (F1_1 * J_neg_2_3 * 2. - F_22_33_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) - 0.5 * self.λ * F_22_33_m * (-J + 1.) * 2.
        out[1] = 0.5 * self.μ * (F1_2 * J_neg_2_3 * 2. + F_21_33_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) + 0.5 * self.λ * F_21_33_m * (-J + 1.) * 2.
        out[2] = 0.5 * self.μ * (F1_3 * J_neg_2_3 * 2. - F_21_32_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) - 0.5 * self.λ * F_21_32_m * (-J + 1.) * 2.
        out[3] = 0.5 * self.μ * (F2_1 * J_neg_2_3 * 2. + F_12_33_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) + 0.5 * self.λ * F_12_33_m * (-J + 1.) * 2.
        out[4] = 0.5 * self.μ * (F2_2 * J_neg_2_3 * 2. - F_11_33_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) - 0.5 * self.λ * F_11_33_m * (-J + 1.) * 2.
        out[5] = 0.5 * self.μ * (F2_3 * J_neg_2_3 * 2. + F_11_32_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) + 0.5 * self.λ * F_11_32_m * (-J + 1.) * 2.
        out[6] = 0.5 * self.μ * (F3_1 * J_neg_2_3 * 2. - F_12_23_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) - 0.5 * self.λ * F_12_23_m * (-J + 1.) * 2.
        out[7] = 0.5 * self.μ * (F3_2 * J_neg_2_3 * 2. + F_11_23_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) + 0.5 * self.λ * F_11_23_m * (-J + 1.) * 2.
        out[8] = 0.5 * self.μ * (F3_3 * J_neg_2_3 * 2. - F_11_22_m * J_neg_5_3 * F_sqnorm * (2. / 3.)) - 0.5 * self.λ * F_11_22_m * (-J + 1.) * 2.
        # @formatter:on

        return out


    def d2E_dF2(self, F: np.ndarray) -> np.ndarray:
        # painstakingly used matlab
        F1_1 = F[0, 0]
        F1_2 = F[0, 1]
        F1_3 = F[0, 2]
        F2_1 = F[1, 0]
        F2_2 = F[1, 1]
        F2_3 = F[1, 2]
        F3_1 = F[2, 0]
        F3_2 = F[2, 1]
        F3_3 = F[2, 2]

        # factor out common terms
        J = np.linalg.det(F)
        J_neg_2_3 = J**(-2. / 3.)
        J_neg_5_3 = J**(-5. / 3.)
        J_neg_8_3 = J ** (-8. / 3.)
        F_sqnorm = np.linalg.norm(F)**2
        F_11_22_m = F[0, 0] * F[1, 1] - F[0, 1] * F[1, 0]
        F_11_32_m = F[0, 0] * F[2, 1] - F[0, 1] * F[2, 0]
        F_21_32_m = F[1, 0] * F[2, 1] - F[1, 1] * F[2, 0]
        F_11_23_m = F[0, 0] * F[1, 2] - F[0, 2] * F[1, 0]
        F_12_23_m = F[0, 1] * F[1, 2] - F[0, 2] * F[1, 1]
        F_11_33_m = F[0, 0] * F[2, 2] - F[0, 2] * F[2, 0]
        F_21_33_m = F[1, 0] * F[2, 2] - F[1, 2] * F[2, 0]
        F_12_33_m = F[0, 1] * F[2, 2] - F[0, 2] * F[2, 1]
        F_22_33_m = F[1, 1] * F[2, 2] - F[1, 2] * F[2, 1]

        # F was flattened row-wise, as in lecture
        # @formatter:off
        out = np.zeros((9, 9))
        out[0, 0] = 0.5*self.μ*(J_neg_2_3*2.+(F_22_33_m**2)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.)-F1_1*(F_22_33_m)*J_neg_5_3*(8./3.))+0.5*self.λ*(F_22_33_m**2)*2.
        out[0, 1] = -0.5*self.μ*(F1_1*(F_21_33_m)*J_neg_5_3*(-4./3.)+F1_2*(F_22_33_m)*J_neg_5_3*(4./3.)+(F_21_33_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_21_33_m)*(F_22_33_m)*2.
        out[0, 2] = -0.5*self.μ*(F1_1*(F_21_32_m)*J_neg_5_3*(4./3.)+F1_3*(F_22_33_m)*J_neg_5_3*(4./3.)-(F_21_32_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_21_32_m)*(F_22_33_m)*2.
        out[0, 3] = -0.5*self.μ*(F1_1*(F_12_33_m)*J_neg_5_3*(-4./3.)+F2_1*(F_22_33_m)*J_neg_5_3*(4./3.)+(F_12_33_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_12_33_m)*(F_22_33_m)*2.
        out[0, 4] = -0.5*self.μ*(F3_3*J_neg_5_3*(F_sqnorm)*(2./3.)+F1_1*(F_11_33_m)*J_neg_5_3*(4./3.)+F2_2*(F_22_33_m)*J_neg_5_3*(4./3.)-(F_11_33_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_33_m)*(F_22_33_m)*2.-0.5*self.λ*F3_3*(-J+1.)*2.
        out[0, 5] = 0.5*self.μ*(F3_2*J_neg_5_3*(F_sqnorm)*(2./3.)+F1_1*(F_11_32_m)*J_neg_5_3*(4./3.)-F2_3*(F_22_33_m)*J_neg_5_3*(4./3.)-(F_11_32_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_32_m)*(F_22_33_m)*2.+0.5*self.λ*F3_2*(-J+1.)*2.
        out[0, 6] = -0.5*self.μ*(F1_1*(F_12_23_m)*J_neg_5_3*(4./3.)+F3_1*(F_22_33_m)*J_neg_5_3*(4./3.)-(F_12_23_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_12_23_m)*(F_22_33_m)*2.
        out[0, 7] = 0.5*self.μ*(F2_3*J_neg_5_3*(F_sqnorm)*(2./3.)+F1_1*(F_11_23_m)*J_neg_5_3*(4./3.)-F3_2*(F_22_33_m)*J_neg_5_3*(4./3.)-(F_11_23_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_23_m)*(F_22_33_m)*2.+0.5*self.λ*F2_3*(-J+1.)*2.
        out[0, 8] = -0.5*self.μ*(F2_2*J_neg_5_3*(F_sqnorm)*(2./3.)+F1_1*(F_11_22_m)*J_neg_5_3*(4./3.)+F3_3*(F_22_33_m)*J_neg_5_3*(4./3.)-(F_11_22_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_22_m)*(F_22_33_m)*2.-0.5*self.λ*F2_2*(-J+1.)*2.
        out[1, 0] = -0.5*self.μ*(F1_1*(F_21_33_m)*J_neg_5_3*(-4./3.)+F1_2*(F_22_33_m)*J_neg_5_3*(4./3.)+(F_21_33_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_21_33_m)*(F_22_33_m)*2.
        out[1, 1] = 0.5*self.μ*(J_neg_2_3*2.+(F_21_33_m**2)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.)+F1_2*(F_21_33_m)*J_neg_5_3*(8./3.))+0.5*self.λ*(F_21_33_m**2)*2.
        out[1, 2] = -0.5*self.μ*(F1_2*(F_21_32_m)*J_neg_5_3*(4./3.)-F1_3*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_21_32_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_21_32_m)*(F_21_33_m)*2.
        out[1, 3] = 0.5*self.μ*(F3_3*J_neg_5_3*(F_sqnorm)*(2./3.)+F1_2*(F_12_33_m)*J_neg_5_3*(4./3.)+F2_1*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_12_33_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_12_33_m)*(F_21_33_m)*2.+0.5*self.λ*F3_3*(-J+1.)*2.
        out[1, 4] = -0.5*self.μ*(F1_2*(F_11_33_m)*J_neg_5_3*(4./3.)-F2_2*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_11_33_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_33_m)*(F_21_33_m)*2.
        out[1, 5] = 0.5*self.μ*(F3_1*J_neg_5_3*(F_sqnorm)*(-2./3.)+F1_2*(F_11_32_m)*J_neg_5_3*(4./3.)+F2_3*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_11_32_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_32_m)*(F_21_33_m)*2.-0.5*self.λ*F3_1*(-J+1.)*2.
        out[1, 6] = -0.5*self.μ*(F2_3*J_neg_5_3*(F_sqnorm)*(2./3.)+F1_2*(F_12_23_m)*J_neg_5_3*(4./3.)-F3_1*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_12_23_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_12_23_m)*(F_21_33_m)*2.-0.5*self.λ*F2_3*(-J+1.)*2.
        out[1, 7] = 0.5*self.μ*(F1_2*(F_11_23_m)*J_neg_5_3*(4./3.)+F3_2*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_11_23_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_23_m)*(F_21_33_m)*2.
        out[1, 8] = 0.5*self.μ*(F2_1*J_neg_5_3*(F_sqnorm)*(2./3.)-F1_2*(F_11_22_m)*J_neg_5_3*(4./3.)+F3_3*(F_21_33_m)*J_neg_5_3*(4./3.)-(F_11_22_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_22_m)*(F_21_33_m)*2.+0.5*self.λ*F2_1*(-J+1.)*2.
        out[2, 0] = -0.5*self.μ*(F1_1*(F_21_32_m)*J_neg_5_3*(4./3.)+F1_3*(F_22_33_m)*J_neg_5_3*(4./3.)-(F_21_32_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_21_32_m)*(F_22_33_m)*2.
        out[2, 1] = -0.5*self.μ*(F1_2*(F_21_32_m)*J_neg_5_3*(4./3.)-F1_3*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_21_32_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_21_32_m)*(F_21_33_m)*2.
        out[2, 2] = 0.5*self.μ*(J_neg_2_3*2.+(F_21_32_m**2)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.)-F1_3*(F_21_32_m)*J_neg_5_3*(8./3.))+0.5*self.λ*(F_21_32_m**2)*2.
        out[2, 3] = -0.5*self.μ*(F3_2*J_neg_5_3*(F_sqnorm)*(2./3.)-F1_3*(F_12_33_m)*J_neg_5_3*(4./3.)+F2_1*(F_21_32_m)*J_neg_5_3*(4./3.)+(F_12_33_m)*(F_21_32_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_12_33_m)*(F_21_32_m)*2.-0.5*self.λ*F3_2*(-J+1.)*2.
        out[2, 4] = 0.5*self.μ*(F3_1*J_neg_5_3*(F_sqnorm)*(2./3.)-F1_3*(F_11_33_m)*J_neg_5_3*(4./3.)-F2_2*(F_21_32_m)*J_neg_5_3*(4./3.)+(F_11_33_m)*(F_21_32_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_33_m)*(F_21_32_m)*2.+0.5*self.λ*F3_1*(-J+1.)*2.
        out[2, 5] = -0.5*self.μ*(F1_3*(F_11_32_m)*J_neg_5_3*(-4./3.)+F2_3*(F_21_32_m)*J_neg_5_3*(4./3.)+(F_11_32_m)*(F_21_32_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_32_m)*(F_21_32_m)*2.
        out[2, 6] = 0.5*self.μ*(F2_2*J_neg_5_3*(F_sqnorm)*(2./3.)-F1_3*(F_12_23_m)*J_neg_5_3*(4./3.)-F3_1*(F_21_32_m)*J_neg_5_3*(4./3.)+(F_12_23_m)*(F_21_32_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_12_23_m)*(F_21_32_m)*2.+0.5*self.λ*F2_2*(-J+1.)*2.
        out[2, 7] = -0.5*self.μ*(F2_1*J_neg_5_3*(F_sqnorm)*(2./3.)-F1_3*(F_11_23_m)*J_neg_5_3*(4./3.)+F3_2*(F_21_32_m)*J_neg_5_3*(4./3.)+(F_11_23_m)*(F_21_32_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_23_m)*(F_21_32_m)*2.-0.5*self.λ*F2_1*(-J+1.)*2.
        out[2, 8] = -0.5*self.μ*(F1_3*(F_11_22_m)*J_neg_5_3*(4./3.)+F3_3*(F_21_32_m)*J_neg_5_3*(4./3.)-(F_11_22_m)*(F_21_32_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_22_m)*(F_21_32_m)*2.
        out[3, 0] = -0.5*self.μ*(F1_1*(F_12_33_m)*J_neg_5_3*(-4./3.)+F2_1*(F_22_33_m)*J_neg_5_3*(4./3.)+(F_12_33_m)*(F_22_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_12_33_m)*(F_22_33_m)*2.
        out[3, 1] = 0.5*self.μ*(F3_3*J_neg_5_3*(F_sqnorm)*(2./3.)+F1_2*(F_12_33_m)*J_neg_5_3*(4./3.)+F2_1*(F_21_33_m)*J_neg_5_3*(4./3.)+(F_12_33_m)*(F_21_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_12_33_m)*(F_21_33_m)*2.+0.5*self.λ*F3_3*(-J+1.)*2.
        out[3, 2] = -0.5*self.μ*(F3_2*J_neg_5_3*(F_sqnorm)*(2./3.)-F1_3*(F_12_33_m)*J_neg_5_3*(4./3.)+F2_1*(F_21_32_m)*J_neg_5_3*(4./3.)+(F_12_33_m)*(F_21_32_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_12_33_m)*(F_21_32_m)*2.-0.5*self.λ*F3_2*(-J+1.)*2.
        out[3, 3] = 0.5*self.μ*(J_neg_2_3*2.+(F_12_33_m**2)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.)+F2_1*(F_12_33_m)*J_neg_5_3*(8./3.))+0.5*self.λ*(F_12_33_m**2)*2.
        out[3, 4] = -0.5*self.μ*(F2_1*(F_11_33_m)*J_neg_5_3*(4./3.)-F2_2*(F_12_33_m)*J_neg_5_3*(4./3.)+(F_11_33_m)*(F_12_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_33_m)*(F_12_33_m)*2.
        out[3, 5] = 0.5*self.μ*(F2_1*(F_11_32_m)*J_neg_5_3*(4./3.)+F2_3*(F_12_33_m)*J_neg_5_3*(4./3.)+(F_11_32_m)*(F_12_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_32_m)*(F_12_33_m)*2.
        out[3, 6] = -0.5*self.μ*(F2_1*(F_12_23_m)*J_neg_5_3*(4./3.)-F3_1*(F_12_33_m)*J_neg_5_3*(4./3.)+(F_12_23_m)*(F_12_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_12_23_m)*(F_12_33_m)*2.
        out[3, 7] = 0.5*self.μ*(F1_3*J_neg_5_3*(F_sqnorm)*(-2./3.)+F2_1*(F_11_23_m)*J_neg_5_3*(4./3.)+F3_2*(F_12_33_m)*J_neg_5_3*(4./3.)+(F_11_23_m)*(F_12_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))+0.5*self.λ*(F_11_23_m)*(F_12_33_m)*2.-0.5*self.λ*F1_3*(-J+1.)*2.
        out[3, 8] = 0.5*self.μ*(F1_2*J_neg_5_3*(F_sqnorm)*(2./3.)-F2_1*(F_11_22_m)*J_neg_5_3*(4./3.)+F3_3*(F_12_33_m)*J_neg_5_3*(4./3.)-(F_11_22_m)*(F_12_33_m)*J_neg_8_3*(F_sqnorm)*(1.E+1/9.))-0.5*self.λ*(F_11_22_m)*(F_12_33_m)*2.+0.5*self.λ*F1_2*(-J+1.)*2.
